import{_ as a,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Restaurar descrição de eventos migrados","description":"","frontmatter":{"title":"Restaurar descrição de eventos migrados","id":"eproc-restaurar-descricao-eventos-migrados","plataforma":"eproc","tribunal":"TJMG","grupo":"Migração PJe (TJMG)","plano":"free","desde":"1.3.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-restaurar-descricao-eventos-migrados"}]]},"headers":[],"relativePath":"funcionalidades/eproc-restaurar-descricao-eventos-migrados.md","filePath":"funcionalidades/eproc-restaurar-descricao-eventos-migrados.md"}'),t={name:"funcionalidades/eproc-restaurar-descricao-eventos-migrados.md"};function d(i,e,n,c,l,u){return o(),r("div",null,e[0]||(e[0]=[s('<h1 id="restaurar-descricao-de-eventos-migrados" tabindex="-1">Restaurar descrição de eventos migrados <a class="header-anchor" href="#restaurar-descricao-de-eventos-migrados" aria-label="Permalink to &quot;Restaurar descrição de eventos migrados&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Em processos migrados do PJe, vários seletores de evento do eproc mostram só &quot;PETIÇÃO&quot; ou &quot;Juntado(a)&quot; no lugar da descrição real. Este recurso memoriza a descrição real a partir da tabela de eventos e a coloca nesses seletores. Na tela de envio de e-mail, também mostra o ID no PJe de cada documento.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc do TJMG</strong>, em processos migrados:</p><ul><li>seletores de evento de outras telas, como a de anexar/vincular documento e a de cadastro de minuta;</li><li>lista de documentos da tela de envio de e-mail.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra a página do processo migrado. O eploc lê a descrição dos eventos da tabela.</li><li>Em seguida, abra a tela desejada (anexar documento, cadastrar minuta, enviar e-mail). Os seletores mostram a descrição real no lugar de &quot;PETIÇÃO&quot; ou &quot;Juntado(a)&quot;.</li><li>Na tela de envio de e-mail, cada documento importado ganha a nota &quot;ID no PJe: &lt;número&gt;&quot;, que pode ser encontrada com Ctrl+F.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>É preciso abrir a página do processo antes. As descrições memorizadas valem por 30 minutos.</li><li>Com vários processos abertos em abas, a substituição só acontece nas telas do último processo cuja página foi aberta.</li></ul>',12)]))}const h=a(t,[["render",d]]);export{p as __pageData,h as default};
